// SPDX-License-Identifier: GPL-3.0-only
// AI-assisted code; see ../NOTICE.md. This diagnostic view follows one device.
const topic = String(msg.topic || '');
const stateMatch = topic.match(/^(.+)\/sensor\/(temperature|humidity|indoor_temperature|indoor_humidity)\/state$/);
const telemetryMatch = topic.match(/^(.+)\/telemetry$/);
if (!stateMatch && !telemetryMatch) return null;

const source = (stateMatch || telemetryMatch)[1];
let reading = Buffer.isBuffer(msg.payload) ? msg.payload.toString('utf8') : msg.payload;
const number = (value) => {
    if (typeof value !== 'number' && typeof value !== 'string') return undefined;
    if (typeof value === 'string' && !value.trim()) return undefined;
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : undefined;
};
let temperature;
let humidity;
let suffix = 'deg F';
let timestamp;

if (stateMatch) {
    const value = number(reading);
    if (stateMatch[2].includes('humidity')) humidity = value;
    else temperature = value;
} else {
    if (typeof reading === 'string') {
        try { reading = JSON.parse(reading); } catch { return null; }
    }
    if (!reading || typeof reading !== 'object' || Array.isArray(reading)) return null;
    temperature = number(reading.temperature_f);
    if (temperature === undefined) {
        temperature = number(reading.temperature_c);
        if (temperature !== undefined) suffix = 'deg C';
    }
    humidity = number(reading.humidity_percent);
    timestamp = reading.timestamp;
}
if (humidity !== undefined && (humidity < 0 || humidity > 100)) humidity = undefined;
if (temperature === undefined && humidity === undefined) return null;

let current = flow.get('currentReading') || {};
// Do not combine values from different devices when a diagnostic wildcard is used.
if (current.source !== source) current = { source };
if (temperature !== undefined) {
    current.temperature = temperature;
    current.temperatureSuffix = suffix;
    let date = new Date();
    if (timestamp !== undefined && timestamp !== null && timestamp !== '') {
        const numeric = number(timestamp);
        const candidate = numeric !== undefined
            ? new Date(numeric < 1000000000000 ? numeric * 1000 : numeric)
            : new Date(timestamp);
        if (!Number.isNaN(candidate.getTime())) date = candidate;
    }
    current.lastReading = date.toLocaleString();
}
if (humidity !== undefined) current.humidity = humidity;
flow.set('currentReading', current);
const format = (value, unit) => value === undefined ? 'No reading yet' : `${value.toFixed(1)} ${unit}`;
return [
    { topic: 'temperature', payload: format(current.temperature, current.temperatureSuffix || 'deg F') },
    { topic: 'humidity', payload: format(current.humidity, '%') },
    { topic: 'last_reading', payload: current.lastReading || 'No temperature reading yet' }
];
